mapper.select:
SELECT DISTINCT r.role_type, r.role_code, r.role_name, employee_roles.scope_code, p.permission_code, p.permission_name, p.resource, p.action, p.description FROM roles r LEFT JOIN role_permissions rp ON r.role_code = rp.role_code LEFT JOIN permissions p ON rp.permission_code = p.permission_code INNER JOIN ( -- System roles: direct from employee SELECT e.system_role AS role_code, NULL AS scope_code, 'SYSTEM' AS role_type FROM employees e WHERE e.client_id = #{clientId} AND e.delete_flag = ${@com.uit.sociuscoremodules.shared.enums.DeleteFlagEnums@NOT_DELETED.value}
UNION ALL
-- Department roles: from department_employees SELECT de.role_code, de.department_code AS scope_code, 'DEPARTMENT' AS role_type FROM department_employees de WHERE de.employee_id = #{clientId} AND de.delete_flag = ${@com.uit.sociuscoremodules.shared.enums.DeleteFlagEnums@NOT_DELETED.value}
UNION ALL
-- Team roles: from team_employees SELECT te.role_code, te.team_code AS scope_code, 'TEAM' AS role_type FROM team_employees te WHERE te.employee_id = #{clientId} AND te.delete_flag = ${@com.uit.sociuscoremodules.shared.enums.DeleteFlagEnums@NOT_DELETED.value} ) employee_roles ON r.role_code = employee_roles.role_code AND r.role_type = employee_roles.role_type WHERE r.delete_flag = ${@com.uit.sociuscoremodules.shared.enums.DeleteFlagEnums@NOT_DELETED.value} ORDER BY r.role_type, employee_roles.scope_code, p.resource, p.action

mapper.sql:
LEFT JOIN role_permissions rp ON r.role_code = rp.role_code
    AND rp.delete_flag = ${@com.uit.sociuscoremodules.shared.enums.DeleteFlagEnums@NOT_DELETED.value}
LEFT JOIN permissions p ON rp.permission_code = p.permission_code
    AND p.delete_flag = ${@com.uit.sociuscoremodules.shared.enums.DeleteFlagEnums@NOT_DELETED.value}
